{"implementation":"def solve(case):
    threshold = case['threshold']
    accepted_ids = []
    diagnostics = []
    for call in case['calls']:
        gain = (call['loss_without_call'] - call['loss_with_call']) / call['prediction_tokens']
        accepted = call.get('parseable', True) and gain >= threshold
        if accepted:
            accepted_ids.append(call['call_id'])
        diagnostics.append({
            'accepted': accepted,
            'call_id': call['call_id'],
            'normalized_gain': gain
        })
    return {
        'accepted_call_ids': accepted_ids,
        'diagnostics': diagnostics
    }"}
